import type { LevelT } from '../../src/lib/schema';

/**
 * Dictionary of phrasal verbs (Unit 22 and Appendix B).
 *
 * Example markup: the phrasal verb is written in braces. A contiguous verb is
 * {turned off}; a separated one is {turned} the lights {off}. The first
 * example of a transitive entry always has the object right after the
 * phrasal verb and uses `obj.noun`, so generators can swap in the pronoun.
 *
 * alsoAccept: other particles that would also be correct in the FIRST example.
 */

export type PvType = 'intransitive' | 'separable' | 'inseparable' | 'three-part';
export type PvTheme = 'work' | 'relationships' | 'travel' | 'problems' | 'money' | 'communication' | 'daily-life' | 'study' | 'health' | 'emotions' | 'technology';

export interface PhrasalVerb {
  id: string;
  verb: string;
  particle: string;
  type: PvType;
  meaning: string;
  /** Formal / Latinate equivalent, base form. */
  formal?: string;
  level: LevelT;
  themes: PvTheme[];
  obj?: { noun: string; pron: string };
  examples: [string, ...string[]];
  alsoAccept?: string[];
  /** Other phrasal verbs with the same meaning (never used as wrong options). */
  synonyms?: string[];
  register?: 'informal' | 'neutral';
}

type Row = Omit<PhrasalVerb, 'id'> & { id?: string };

