function slug(r: Row): string {
  return `${r.verb}-${r.particle.replace(/\s+/g, '-')}`;
}

/** Parsed and de-duplicated dictionary. */
export const PHRASAL_VERBS: PhrasalVerb[] = (() => {
  const seen = new Set<string>();
  const out: PhrasalVerb[] = [];
  for (const r of ROWS) {
    const id = r.id ?? slug(r);
    if (seen.has(id)) throw new Error(`Duplicate phrasal verb id: ${id}`);
    seen.add(id);
    out.push({ ...r, id });
  }
  return out;
})();

export const PARTICLES = ['up', 'down', 'out', 'off', 'on', 'over', 'through', 'away', 'back', 'in', 'into', 'across', 'along', 'round', 'around', 'about', 'forward', 'aside', 'by', 'ahead', 'after', 'for', 'with', 'without'] as const;

/** Core meanings of the particles (Unit 22.3). */
export const PARTICLE_SENSES: Array<{ particle: string; senses: string; examples: string[] }> = [
  { particle: 'up', senses: 'increase; completion (“to the end”); approach; appearance', examples: ['speed up', 'use up', 'turn up', 'come up', 'sum up'] },
  { particle: 'down', senses: 'reduction; recording on paper; stopping or defeat', examples: ['slow down', 'write down', 'break down', 'turn down', 'shut down'] },
  { particle: 'out', senses: 'exhaustiveness and completion; discovery; exclusion; disappearance', examples: ['run out', 'find out', 'leave out', 'rule out', 'die out'] },
  { particle: 'off', senses: 'separation and departure; cancellation; disconnection', examples: ['take off', 'set off', 'call off', 'turn off', 'lay off'] },
  { particle: 'on', senses: 'continuation; attachment; activation', examples: ['carry on', 'go on', 'put on', 'turn on', 'hold on'] },
  { particle: 'over', senses: 'reviewing; transfer of control; recovery', examples: ['go over', 'think over', 'take over', 'hand over', 'get over'] },
  { particle: 'through', senses: 'from beginning to end; success in reaching someone', examples: ['read through', 'go through', 'see through', 'get through', 'fall through'] },
  { particle: 'away', senses: 'distance and removal; giving to others', examples: ['throw away', 'put away', 'give away', 'pass away', 'get away with'] },
  { particle: 'back', senses: 'return; reply; restraint; reversal of a decision', examples: ['call back', 'pay back', 'hold back', 'take back', 'go back on'] },
  { particle: 'in / into', senses: 'entering; submitting; inclusion; investigation or meeting', examples: ['hand in', 'fill in', 'check in', 'look into', 'run into'] },
  { particle: 'across', senses: 'communication from one person to another; chance meeting', examples: ['get across', 'put across', 'come across'] },
  { particle: 'along / around / round', senses: 'cooperation and relationships; movement in a place; visiting; change of direction', examples: ['get along with', 'go along with', 'show around', 'come round', 'turn around'] },
];

export function pvLabel(pv: PhrasalVerb): string {
  return `${pv.verb} ${pv.particle}`;
}
